{"content": "1|// graph_health — single trustable answer to "is the graph usable right now?"
2|//
3|// Echoes PM feedback 2026-04-21: "To answer 'is the graph usable right now?'
4|// an agent has to call graph_index, read brief.plan.md, parse the TRUST line,
5|// cross-reference. All three can disagree." This verb aggregates those signals
6|// into one response so a session can check health in a single call.
7|//
8|// Synthesis-only. No new data — just a coherent view of what graph_status +
9|// the overlay validator + the brief's trust logic already expose.
10|
11|import { join, dirname } from 'node:path';
12|import { graphCapabilities } from '../graph-capabilities.mjs';
13|import { getBackend } from '../../code-intel/backends.js';
14|import { existsSync, readFileSync, statSync } from 'node:fs';
15|import { fileURLToPath } from 'node:url';
16|import { execFileSync } from 'node:child_process';
17|
18|// HOW MUCH OF THE COLLECTION'S EVIDENCE HAS ALREADY DECAYED.
19|//
20|// The salvage gate drops verified evidence per FILE: a covered file that changed since the
21|// collection loses it on the next rebuild. So the honest magnitude is "how many of the files this
22|// collection covered have changed", not "how many commits have passed" — 121 commits that touch no
23|// covered file destroy nothing, and one that rewrites forty covered files destroys a great deal.
24|//
25|// Returns nulls rather than zeros when it cannot tell. A zero here would read as "nothing decayed",
26|// which is the permissive answer, and this feeds the message a reader consults before deleting code.
27|//
28|// ⛔ THIS WAS ONE FUNCTION AND IT RAN GIT INSIDE A PINNED READ SNAPSHOT. graph_health called it
29|// from within captureExistingSnapshot, so the WAL reader stayed open across an execFileSync — the
30|// precise design this repository rejected, done in the function whose whole purpose was to read
31|// every authority input at one instant. The comment beside the call even justified it: reading
32|// these together IS the window being closed, so the fix looked deliberate and the cost was invisible.
33|//
34|// ⇒ Split by substrate. `collectionCoveredFiles` is pure database and is safe under a pin;
35|// `decayFromCoveredFiles` takes the list it produced and does the git work with no handle open.
36|
37|/** The files a collection covered, straight from the graph. Pure DB — safe inside a pinned read. */
38|export function collectionCoveredFiles(db, latest) {
39|  if (!latest?.collectionId) return null;
40|  try {
41|    return db.all(
42|      'SELECT DISTINCT file FROM code_intel_records WHERE collection_id = $cid',
43|      { cid: latest.collectionId },
44|    ).map((r) => r.file).filter(Boolean);
45|  } catch {
46|    return null;
47|  }
48|}
49|
50|/** git diff plus arithmetic over an ALREADY-READ file list. Takes no database handle, by design. */
51|export function decayFromCoveredFiles(covered, latest, head, repoRoot) {
52|  const unknown = { filesCovered: null, filesChangedSinceCollection: null };
53|  if (!latest?.indexedCommit || !head || !repoRoot) return unknown;
54|  try {
55|    if (!Array.isArray(covered) || covered.length === 0) return unknown;
56|    const out = execFileSync(
57|      'git',
58|      ['-C', repoRoot, 'diff', '--name-only', `${latest.indexedCommit}..${head}`],
59|      { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] },
60|    );
61|    const changed = new Set(out.split(/\r?\n/).map((l) => l.trim()).filter(Boolean));
62|    // Records may store OS-native separators; git always reports forward slashes.
63|    const norm = (f) => String(f).replace(/\\/gu, '/');
64|    return {
65|      filesCovered: covered.length,
66|      filesChangedSinceCollection: covered.filter((f) => changed.has(norm(f))).length,
67|    };
68|  } catch {
69|    return unknown;
70|  }
71|}
