{"content": "1|// THE DENOMINATOR DECIDES WHETHER A COVERAGE NUMBER MEANS ANYTHING.
2|//
3|// Dividing verified edges by EVERY CALLS edge reported 12% on a repo where every
4|// verifiable edge had in fact been verified. That reads as a coverage failure and was an
5|// accounting one — and the field test checked the 833/1599 arithmetic against this exact
6|// field, which makes it one of the few they confirmed they actually use.
7|//
8|// ★★ CONVERTED FROM SOURCE-GREP 2026-08-11.
9|//
10|// The previous version was eight regexes over health.js: `verified / verifiable`,
11|// `verifiable_and_in_scope_calls`, `lspOutOfScopeCalls`, `LSP_VERIFIABLE_LANGUAGES`, and
12|// so on. Every one asserts SPELLING. None could fail on a wrong number — and a wrong
13|// number is the entire failure mode of a coverage statistic.
14|//
15|// The computation was inline in health.js, which is why it had never been tested by
16|// running it. It now lives in `query/coverage-denominator.js` and this calls it with rows
17|// and compares integers.
18|import { describe, it, expect } from 'vitest';
19|import { computeCoverage, LSP_VERIFIABLE_LANGUAGES } from '../../../mcp/stdio/query/coverage-denominator.js';
20|
21|describe('lsp coverage denominator', () => {
22|  it('★★ divides by the VERIFIABLE subset, not by every CALLS edge', () => {
23|    // The original defect, as arithmetic. 100 C++ edges all verified, plus 700 JS edges
24|    // no backend here can verify. The honest answer is 100%; dividing by 800 gives 12%.
25|    const rows = [
26|      { lang: 'cpp', c: 100, inScope: true },
27|      { lang: 'javascript', c: 700, inScope: true },
28|    ];
29|    const r = computeCoverage(rows, 100);
30|
31|    expect(r.verifiable, 'JS edges are not verifiable by this backend').toBe(100);
32|    expect(r.pct, 'every verifiable edge was verified — that is 100%, not 12%').toBe(100);
33|  });
34|
35|  it('★★ out-of-scope edges never enter the denominator', () => {
36|    // Attack nine: an edge outside the tracked corpus is not verification debt.
37|    const rows = [
38|      { lang: 'cpp', c: 50, inScope: true },
39|      { lang: 'cpp', c: 950, inScope: false },
40|    ];
41|    const r = computeCoverage(rows, 50);
42|
43|    expect(r.verifiable).toBe(50);
44|    expect(r.outOfScope).toBe(950);
45|    expect(r.pct).toBe(100);
46|  });
47|
48|  it('★★ and out-of-scope edges do NOT migrate in when their language becomes verifiable', () => {
49|    // The subtler half of attack nine, and the one a spelling test cannot express: an
50|    // out-of-scope C++ edge is ALREADY in a verifiable language. If scope were ignored it
51|    // would sit in the denominator and drag the percentage down for a corpus we never
52|    // claimed to cover. Scope is checked FIRST, independently of language.
53|    const inScopeOnly = computeCoverage([{ lang: 'cpp', c: 10, inScope: true }], 10);
54|    const withOutOfScope = computeCoverage([
55|      { lang: 'cpp', c: 10, inScope: true },
56|      { lang: 'cpp', c: 10_000, inScope: false },
57|    ], 10);
58|
59|    expect(withOutOfScope.pct, 'adding out-of-scope work must not change coverage')
60|      .toBe(inScopeOnly.pct);
61|  });
62|
63|  it('★ reports the excluded population separately, with a reason per language', () => {
64|    // Excluding silently would be the same defect wearing a better number — the reader
65|    // must be able to see what was taken out and why.
66|    const r = computeCoverage([
67|      { lang: 'cpp', c: 10, inScope: true },
68|      { lang: 'javascript', c: 40, inScope: true },
69|      { lang: 'python', c: 5, inScope: true },
70|    ], 10);
71|
72|    expect(r.unverifiable.map((u) => u.lang).sort()).toEqual(['javascript', 'python']);
73|    expect(r.unverifiable.every((u) => u.reason === 'non_cpp_language')).toBe(true);
74|    expect(r.unverifiable.reduce((a, u) => a + u.count, 0)).toBe(45);
75|  });
76|
77|  it('★ the denominator names its own population', () => {
78|    // §4's basis rule: a ratio that travels without its denominator is how two correct
79|    // numbers produce a wrong comparison. This is the field the field test used to check the
80|    // 833/1599 arithmetic.
81|    expect(computeCoverage([], 0).denominator).toBe('verifiable_and_in_scope_calls');
82|  });
83|
84|  it('a zero denominator reports 0, never NaN', () => {
85|    // A NaN percentage renders as a plausible-looking blank rather than as an error.
86|    const r = computeCoverage([{ lang: 'javascript', c: 10, inScope: true }], 0);
87|    expect(r.verifiable).toBe(0);
88|    expect(r.pct).toBe(0);
89|    expect(Number.isNaN(r.pct)).toBe(false);
90|  });
91|
92|  it('verifiability is scoped to languages a backend here actually covers', () => {
93|    // Kept as a structural assertion because the SET is the contract — but on the
94|    // exported value, not on a regex over the file that happens to define it.
95|    expect(LSP_VERIFIABLE_LANGUAGES.has('cpp')).toBe(true);
96|    expect(LSP_VERIFIABLE_LANGUAGES.has('javascript')).toBe(false);
97|    expect(LSP_VERIFIABLE_LANGUAGES.has('python')).toBe(false);
98|  });
99|});", "total_lines": 99, "file_size": 4855, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|// A COLLECTION EXISTING IS NOT A COLLECTION COVERING ANYTHING.
2|//
3|// ⛔ FOUND BY RUNNING THE FIRST CODE-INTEL COLLECTION THIS REPO HAS EVER HAD. `graph_health` had
4|// been naming "no code-intel collection" as its top next action for the life of the repo, so I ran
5|// one — scoped to three files, to see whether it worked at all. It did. And then:
6|//
7|//     the response said        filesProcessed 3 · filesTotal 3      -> reads as 100%
8|//     the stored row said      status ok, mode null                 -> no scope recorded at all
9|//     graph_health then said   nextActions: []                      -> its ONLY code-intel
10|//                                                                       warning went silent
11|//
12|// `filesTotal` was the SCOPE's denominator, not the repo's. 3 of 3 is complete. 3 of 484 is 0.6%.
13|// Same defect as every other denominator this repo has shipped: a ratio over the population the
14|// code happened to look at rather than the population the claim is about.
15|//
16|// ⚠ AND `nextActions: []` IS DOCUMENTED AS MEANING A HEALTHY REPO — "EMPTY on a healthy repo,
17|// which is what makes a populated list mean something". So a 0.6% collection did not merely fail
18|// to warn; it actively asserted health.
19|import { describe, it, expect, afterEach } from 'vitest';
20|import { mkdtemp, rm, mkdir, writeFile } from 'node:fs/promises';
21|import { tmpdir } from 'node:os';
22|import { join } from 'node:path';
23|import { execFileSync } from 'node:child_process';
24|import { graphHealth } from '../../../mcp/stdio/query/verbs/health.js';
25|import { openDb } from '../../../mcp/stdio/storage/db.js';
26|import { ensureCodeIntelCollectionsTable, ensureCodeIntelRecordsTable } from '../../../mcp/stdio/storage/schema.js';
27|import { expectAbsentWithLiveMatcher } from '../../helpers/live-matcher.js';
28|
29|let repo;
30|afterEach(async () => {
31|  if (repo) { try { await rm(repo, { recursive: true, force: true }); } catch { /* win lock */ } }
32|  repo = undefined;
33|});
34|
35|/**
36| * A repo with a graph, lsp-verified edges, and a collection row we control.
37| *
38| * ⚠ `verifiedEdges` IS A POPULATION, NOT A COUNT. The default keeps the single edge every existing
39| * test here relies on. A caller that passes its own list is separating two things the fixture used
40| * to fuse: how many files carry compiler-verified edges, and how many files a collection recorded.
41| */
42|async function repoWithCollection(coverage, {
43|  verifiedEdges = [{ file: 'src/a.ts', relation: 'CALLS' }],
44|} = {}) {
45|  repo = await mkdtemp(join(tmpdir(), 'apg-cov-'));
46|  await mkdir(join(repo, '.aify-graph'), { recursive: true });
47|  execFileSync('git', ['-C', repo, 'init', '-q'], { stdio: 'ignore' });
48|  execFileSync('git', ['-C', repo, '-c', 'user.email=t@t', '-c', 'user.name=t',
49|    'commit', '--allow-empty', '-qm', 'i'], { stdio: 'ignore' });
50|  const commit = execFileSync('git', ['-C', repo, 'rev-parse', 'HEAD'], { encoding: 'utf8' }).trim();
51|  await writeFile(join(repo, '.aify-graph', 'manifest.json'), JSON.stringify({
52|    commit, indexedAt: new Date().toISOString(), nodes: 2, edges: 1, schemaVersion: 4,
53|    extractorVersion: '0.1.0', status: 'ok', dirtyFiles: [], dirtyEdges: [], dirtyEdgeCount: 0,
54|  }));
55|  const db = openDb(join(repo, '.aify-graph', 'graph.sqlite'));
56|  ensureCodeIntelCollectionsTable(db);
57|  const node = (id, file) => db.run(
58|    `INSERT INTO nodes (id,type,label,file_path,start_line,end_line,language,confidence,extra)
59|     VALUES ($id,'Function',$id,$f,1,1,'typescript',1,'{}')`, { id, f: file });
60|  node('a', 'src/a.ts'); node('b', 'src/b.ts');
61|  // ⛔ THE FIXTURE NOW BUILDS THE POPULATION IT CLAIMS, AND THAT IS THE FIX RATHER THAN THE COST.
62|  //
63|  // It used to insert TWO file nodes and store `files_eligible: 484`. Health read the stored number
64|  // and agreed, so the test passed against a graph that contradicted its own denominator. Once
65|  // health began MEASURING eligibility instead of trusting the row, the live answer was 2 — correct
66|  // about the graph, and fatal to a fixture asserting 484.
67|  //
68|  // ⇒ A fixture that states a number the artifact does not contain can only ever test that the
69|  // number was echoed back. Building the files makes the ratio real.
70|  if (coverage.eligible != null) {
71|    for (let i = 0; i < coverage.eligible - 2; i += 1) node(`e${i}`, `src/gen/e${i}.ts`);
72|  }
73|  // Records are what `coveredFileCount` counts — the numerator is now measured across every live
74|  // collection rather than taken from the latest one's `files_processed`.
75|  ensureCodeIntelRecordsTable(db);
76|  for (let i = 0; i < (coverage.processed ?? 0); i += 1) {
77|    const f = i === 0 ? 'src/a.ts' : i === 1 ? 'src/b.ts' : `src/gen/e${i - 2}.ts`;
78|    db.run(
79|      `INSERT INTO code_intel_records (collection_id,kind,language,symbol_id,qname,file,raw)
80|       VALUES ('c1','references','typescript',$s,$q,$f,'{}')`,
81|      { s: `s${i}`, q: `q${i}`, f },
82|    );
83|  }
84|  // ⚠ An lsp-verified edge, so the "no [lsp✓] edges" branch cannot be what fires. Without this
85|  // the test would pass against a completely different condition.
86|  // ⚠ THE ENDPOINTS VARY, BECAUSE THE SCHEMA SAYS THEY MUST. `idx_edges_unique` is
87|  // (from_id, to_id, relation), so a second edge a→b CALLS is not a second edge — it is a
88|  // constraint violation, and the fixture would be asserting against a graph it failed to build.
89|  verifiedEdges.forEach((e, i) => {
90|    db.run(
91|      `INSERT INTO edges (from_id,to_id,relation,source_file,source_line,confidence,provenance,extractor)
92|       VALUES ('a',$to,$r,$f,1,1,'LSP_VERIFIED','ts-langserver')`,
93|      { to: i === 0 ? 'b' : `e${i - 1}`, r: e.relation, f: e.file },
94|    );
95|  });
96|  db.run(
97|    `INSERT INTO code_intel_collections
98|       (collection_id, provider, provider_version, project_root, language, status,
99|        collected_at, index_ready, files_processed, files_in_scope, files_eligible)
100|     VALUES ('c1','ts-langserver','0.1.0',$root,'typescript','ok',$at,1,$p,$s,$e)`,
101|    {
102|      root: repo, at: new Date().toISOString(),
103|      p: coverage.processed, s: coverage.inScope, e: coverage.eligible,
104|    });
105|  db.close();
106|  return repo;
107|}
108|
109|// ⚠ THE LOCATOR NAMES BOTH NOUNS THE BRANCH CAN USE. It matched only "code-intel collection", so
110|// rewording the coverage sentence to say what it actually counts — records — would have made every
